import{_ as i,I as r,o as g,c,j as t,a as h,J as a,w as p,a4 as d}from"./chunks/framework.Co6Rcm-5.js";const _=JSON.parse('{"title":"论文速读","description":"模型、强化学习、Agent、VLA、数据、评估与理论资料的主题化阅读索引。","frontmatter":{"title":"论文速读","description":"模型、强化学习、Agent、VLA、数据、评估与理论资料的主题化阅读索引。","pageClass":"paper-reading-page"},"headers":[],"relativePath":"paper-reading/index.md","filePath":"paper-reading/index.md","lastUpdated":1786522313000}'),b={name:"paper-reading/index.md"};function m(u,e,k,f,x,A){const o=r("SummaryHero"),n=r("ResearchWorkbench"),s=r("PaperCatalog"),l=r("PaperPageNavigator");return g(),c("div",null,[e[1]||(e[1]=t("h1",{id:"论文速读",tabindex:"-1"},[h("论文速读 "),t("a",{class:"header-anchor",href:"#论文速读","aria-label":"Permalink to “论文速读”"},"​")],-1)),a(o,{goals:["理解研究问题","掌握关键机制与公式","形成可验证的工程判断"],duration:"约 15 分钟",output:"完整论文阅读地图"},{default:p(()=>[...e[0]||(e[0]=[t("p",null,"本页由“论文速读”原始笔记按主题重组。每项资料直接说明阅读用途与需要继续核验的边界，便于按主题定位和延伸阅读。",-1)])]),_:1}),a(n,{preset:"overview"}),a(s),a(l),e[2]||(e[2]=d('<h2 id="ai-辅助阅读-模型" tabindex="-1">AI 辅助阅读：模型 <a class="header-anchor" href="#ai-辅助阅读-模型" aria-label="Permalink to “AI 辅助阅读：模型”">​</a></h2><h3 id="model-attention-residuals" tabindex="-1">1. Attention Residuals <a class="header-anchor" href="#model-attention-residuals" aria-label="Permalink to “1. Attention Residuals”">​</a></h3><blockquote><p><strong>资料</strong>：<a href="https://li.feishu.cn/docx/DqjKdMYtroIIncxD9nmcDpJWnRe" target="_blank" rel="noreferrer">Attention-residuals</a></p><p><strong>用途</strong>：关注注意力层与残差路径的结构设计，用于理解信息在深层网络中的保留、组合与稳定传播。</p><p><strong>核验 / 局限</strong>：核验具体结构、对照基线、参数量和训练预算；仅有标题无法判断收益来自架构本身还是训练配置。</p></blockquote><h3 id="model-type-system-ai-coding" tabindex="-1">2. 类型系统与 AI Coding <a class="header-anchor" href="#model-type-system-ai-coding" aria-label="Permalink to “2. 类型系统与 AI Coding”">​</a></h3><blockquote><p><strong>资料</strong>：<a href="https://li.feishu.cn/docx/Ry7vdNtXVoSoRExQuzucexAanhb" target="_blank" rel="noreferrer">summary-type-system-ai-coding-20260318</a></p><p><strong>用途</strong>：聚焦类型系统与 AI Coding 的结合，用于分析类型信息如何约束代码生成、补全和静态验证。</p><p><strong>核验 / 局限</strong>：继续确认覆盖的语言、错误类型、评测集与实际修复率；类型正确不等于业务语义正确。</p></blockquote><h3 id="model-skill-evaluation" tabindex="-1">3. Skill 评估 <a class="header-anchor" href="#model-skill-evaluation" aria-label="Permalink to “3. Skill 评估”">​</a></h3><blockquote><p><strong>资料</strong>：<a href="https://agentskills.io/skill-creation/evaluating-skills" target="_blank" rel="noreferrer">Skill 评估指南</a></p><p><strong>用途</strong>：提供 Skill 创建后的评估入口，用于设计成功率、稳定性、触发准确性和回归测试。</p><p><strong>核验 / 局限</strong>：需要把通用指南转换为项目自己的任务集、失败分类与人工基线，并检查文档版本及适用平台。</p></blockquote><h3 id="model-llama-nemotron" tabindex="-1">4. Llama Nemotron <a class="header-anchor" href="#model-llama-nemotron" aria-label="Permalink to “4. Llama Nemotron”">​</a></h3><blockquote><p><strong>资料</strong>：<a href="https://li.feishu.cn/docx/ZgMfdjYN6oxFnZx1I5wcL8t9nZg" target="_blank" rel="noreferrer">summary-llama-nemotron-20260325</a></p><p><strong>用途</strong>：了解 Llama Nemotron 的模型定位、训练方法与推理能力，作为开放模型选型材料。</p><p><strong>核验 / 局限</strong>：核验模型具体版本、许可证、上下文长度、推理成本及公开基准的复现条件，避免跨版本比较。</p></blockquote><h3 id="model-nemotron-cascade-2" tabindex="-1">5. Nemotron Cascade 2 <a class="header-anchor" href="#model-nemotron-cascade-2" aria-label="Permalink to “5. Nemotron Cascade 2”">​</a></h3><blockquote><p><strong>资料</strong>：<a href="https://li.feishu.cn/docx/VLyrd8YeUoZTNUx8Cn0cmlj4nJb" target="_blank" rel="noreferrer">summary-nemotron-cascade2-20260325</a></p><p><strong>用途</strong>：关注级联式训练或推理方案，用于比较单模型与多阶段能力增强路线。</p><p><strong>核验 / 局限</strong>：确认 Cascade 2 的阶段定义、数据流、教师信号和消融实验，并衡量级联带来的延迟与成本。</p></blockquote><h3 id="model-agentic-capability-glm5" tabindex="-1">6. Agentic 能力拆解 <a class="header-anchor" href="#model-agentic-capability-glm5" aria-label="Permalink to “6. Agentic 能力拆解”">​</a></h3><blockquote><p><strong>资料</strong>：<a href="https://li.feishu.cn/docx/QvWBdezN3orc6mxvnpPctuf2nxd" target="_blank" rel="noreferrer">Agentic 能力拆解</a>，拆分 GLM-5 的训练全过程。</p><p><strong>用途</strong>：建立预训练、后训练、工具使用与任务评估之间的 Agent 能力地图。</p><p><strong>核验 / 局限</strong>：区分公开事实、作者推断和经验总结，并核验训练数据、奖励设计、工具环境及各阶段贡献。</p></blockquote><h3 id="model-gemma-4-31b-it" tabindex="-1">7. Gemma 4 31B IT <a class="header-anchor" href="#model-gemma-4-31b-it" aria-label="Permalink to “7. Gemma 4 31B IT”">​</a></h3><blockquote><p><strong>资料</strong>：<a href="https://li.feishu.cn/docx/GYA2dKRQRosJeMxwlELcki1pnVb" target="_blank" rel="noreferrer">gemma-4-31b-it-analysis</a></p><p><strong>用途</strong>：面向 Gemma 4 31B 指令模型的技术解读，用于模型能力、部署资源和适用场景选型。</p><p><strong>核验 / 局限</strong>：核验正式模型卡、许可证、量化影响、硬件吞吐和目标任务实测；单一综合榜单不足以支撑生产选型。</p></blockquote><h3 id="model-hy-omniweaving" tabindex="-1">8. HY-OmniWeaving <a class="header-anchor" href="#model-hy-omniweaving" aria-label="Permalink to “8. HY-OmniWeaving”">​</a></h3><blockquote><p><strong>资料</strong>：<a href="https://li.feishu.cn/docx/CdCqdc1cOoPXVexrN3jcOC7Unoc" target="_blank" rel="noreferrer">HY-OmniWeaving-Analysis</a></p><p><strong>用途</strong>：关注混元 OmniWeaving 的多模态或全模态能力组织方式，用于理解跨模态生成与统一建模路线。</p><p><strong>核验 / 局限</strong>：确认实际支持的模态、输入输出限制、数据与安全过滤策略，并通过跨模态一致性案例验证效果。</p></blockquote><h3 id="model-qwen-3-6-27b" tabindex="-1">9. Qwen3.6-27B <a class="header-anchor" href="#model-qwen-3-6-27b" aria-label="Permalink to “9. Qwen3.6-27B”">​</a></h3><blockquote><p><strong>资料</strong>：<a href="https://li.feishu.cn/docx/S1Iddd2WGoSHcSxMXutcB9DNnDh" target="_blank" rel="noreferrer">Qwen3.6-27B 深度技术解读</a></p><p><strong>用途</strong>：了解 Qwen3.6-27B 的架构、训练和能力边界，支持同尺寸模型的选型比较。</p><p><strong>核验 / 局限</strong>：核验模型版本与官方材料，统一精度、上下文、硬件和提示词后再比较；关注中文、代码和 Agent 任务的分项表现。</p></blockquote><h3 id="model-lora-vs-sft" tabindex="-1">10. LoRA 与 SFT 参数 <a class="header-anchor" href="#model-lora-vs-sft" aria-label="Permalink to “10. LoRA 与 SFT 参数”">​</a></h3><blockquote><p><strong>资料</strong>：<a href="https://thinkingmachines.ai/blog/lora/" target="_blank" rel="noreferrer">LoRA 技术文章</a></p><p><strong>用途</strong>：探究 LoRA 和 SFT 的参数关系，用于理解低秩适配的可训练参数、容量和微调成本。</p><p><strong>核验 / 局限</strong>：复核公式、秩与显存/效果的关系，并在目标模型和数据上做全参 SFT 对照；单篇博客结论不宜直接泛化。</p></blockquote><h2 id="ai-辅助阅读-产品相关" tabindex="-1">AI 辅助阅读：产品相关 <a class="header-anchor" href="#ai-辅助阅读-产品相关" aria-label="Permalink to “AI 辅助阅读：产品相关”">​</a></h2><h3 id="product-codemender" tabindex="-1">11. CodeMender 自动修复安全漏洞 <a class="header-anchor" href="#product-codemender" aria-label="Permalink to “11. CodeMender 自动修复安全漏洞”">​</a></h3><blockquote><p><strong>资料</strong>：<a href="https://li.feishu.cn/docx/BxlcdAkLGoVEiUxYCIVc0LxanMe" target="_blank" rel="noreferrer">CodeMender：AI Agent 如何自动修复代码安全漏洞</a></p><p><strong>用途</strong>：关注漏洞发现、补丁生成和验证闭环，用于设计安全修复 Agent 的工作流。</p><p><strong>核验 / 局限</strong>：核验漏洞集、补丁正确率、测试与静态分析门禁、误修率及人工介入比例；“生成补丁”不能替代可利用性与回归验证。</p></blockquote><h3 id="product-human-ai-collaboration" tabindex="-1">12. 人与 AI 的 Coding 协作边界 <a class="header-anchor" href="#product-human-ai-collaboration" aria-label="Permalink to “12. 人与 AI 的 Coding 协作边界”">​</a></h3><blockquote><p><strong>资料</strong>：<a href="https://li.feishu.cn/slides/WBS6sdF4PlLDnwdwJPIcks1enEU" target="_blank" rel="noreferrer">探索人与 AI 协作的边界——AI Coding 领域</a></p><p><strong>用途</strong>：分析人机分工、审查责任和 AI Coding 的适用边界。</p><p><strong>核验 / 局限</strong>：提炼可量化的人效、质量和风险指标，并用真实开发任务验证；经验性案例可能受团队成熟度影响。</p></blockquote><h3 id="product-anthropic-agent-evals" tabindex="-1">13. Anthropic Agent Evals <a class="header-anchor" href="#product-anthropic-agent-evals" aria-label="Permalink to “13. Anthropic Agent Evals”">​</a></h3><blockquote><p><strong>资料</strong>：<a href="https://li.feishu.cn/wiki/Jl4JwUUeYidHhxkUk5MclEodnEh" target="_blank" rel="noreferrer">面向 Agent 场景的评估方法——Anthropic Agent Evals 探索</a></p><p><strong>用途</strong>：构建多步任务、工具调用、轨迹质量和最终结果相结合的 Agent 评估体系。</p><p><strong>核验 / 局限</strong>：核验任务代表性、评分器一致性、重复运行方差与污染风险；终态成功率之外还应记录成本和失败轨迹。</p></blockquote><h3 id="product-agent-insight-agenthub" tabindex="-1">14. agent-insight 与 AgentHub <a class="header-anchor" href="#product-agent-insight-agenthub" aria-label="Permalink to “14. agent-insight 与 AgentHub”">​</a></h3><blockquote><p><strong>资料</strong>：<a href="https://gitcode.com/openeuler/agent-insight#%E4%BC%98%E5%8C%96-skill" target="_blank" rel="noreferrer">agent-insight：基于 Agent 生态的 Skill 生成优化与评估平台</a> / <a href="https://www.agenthub.build/?ref=huntscreens.com" target="_blank" rel="noreferrer">AgentHub</a></p><p><strong>用途</strong>：前者面向 Skill 生成、优化与评估，后者可作为 Agent / Skill 生态参考，用于比较资产生产和分发方式。</p><p><strong>核验 / 局限</strong>：分别核验开源代码、维护活跃度、评估可复现性与平台收录规则；两个链接定位不同，不能把生态展示当成能力质量证明。</p></blockquote><h3 id="product-openclaw-distributed-platform" tabindex="-1">15. OpenClaw 分布式 Agent Platform <a class="header-anchor" href="#product-openclaw-distributed-platform" aria-label="Permalink to “15. OpenClaw 分布式 Agent Platform”">​</a></h3><blockquote><p><strong>资料</strong>：<a href="https://lfc-qu3actyc.cnhb01-dev.fc.chj.cloud/index.html" target="_blank" rel="noreferrer">分布式 Agent Platform 与多人协作 Agentic Loop</a></p><p><strong>用途</strong>：把 OpenClaw 做成分布式 Agent Platform，同时跑通多人协作的 Agentic Loop，用于观察编排、状态同步与协作界面。</p><p><strong>核验 / 局限</strong>：实测并发、故障恢复、权限隔离、状态一致性和可观测性；临时部署地址的可用性与实现细节可能变化。</p></blockquote><h3 id="product-frontend-tech-stack" tabindex="-1">16. 前端技术栈 <a class="header-anchor" href="#product-frontend-tech-stack" aria-label="Permalink to “16. 前端技术栈”">​</a></h3><blockquote><p><strong>资料</strong>：<a href="https://chatgpt.com/share/6a420fb0-db04-83ec-b9bf-2245ced877b3" target="_blank" rel="noreferrer">ChatGPT 共享讨论</a></p><p><strong>用途</strong>：记录前端技术选型线索，用于快速回顾框架、组件和工程方案。</p><p><strong>核验 / 局限</strong>：共享对话可能失效或缺少最终决策上下文；应把候选方案与当前仓库依赖、构建体积、可访问性和维护成本逐项核验。</p></blockquote><h3 id="product-ui-design" tabindex="-1">17. UI 设计参考 <a class="header-anchor" href="#product-ui-design" aria-label="Permalink to “17. UI 设计参考”">​</a></h3><blockquote><p><strong>资料</strong>：<a href="https://juejin.cn/post/7073442264688623647" target="_blank" rel="noreferrer">掘金文章</a>、<a href="https://zhuanlan.zhihu.com/p/664783228" target="_blank" rel="noreferrer">知乎文章</a></p><p><strong>用途</strong>：整理布局、视觉层级和交互设计原则。</p><p><strong>核验 / 局限</strong>：核验文章发布时间、目标端和设计规范，并通过实际页面的桌面/移动端、深浅色与键盘操作验证；参考案例不等于可直接复用的设计系统。</p></blockquote><h3 id="product-easy-vibe-frontend" tabindex="-1">18. Easy Vibe 前端 <a class="header-anchor" href="#product-easy-vibe-frontend" aria-label="Permalink to “18. Easy Vibe 前端”">​</a></h3><blockquote><p><strong>资料</strong>：<a href="https://datawhalechina.github.io/easy-vibe/zh-cn/stage-2/frontend/figma-mastergo/" target="_blank" rel="noreferrer">Easy Vibe：Figma / MasterGo</a></p><p><strong>用途</strong>：提供从设计工具到前端实现的学习路径，用于建立原型和设计交付基础。</p><p><strong>核验 / 局限</strong>：按当前工具版本走通完整示例，并确认导出物、组件规范和代码实现之间的差距；教程流程未必覆盖生产工程约束。</p></blockquote><h2 id="业务算法" tabindex="-1">业务算法 <a class="header-anchor" href="#业务算法" aria-label="Permalink to “业务算法”">​</a></h2><h3 id="business-multimodal-moderation" tabindex="-1">1. 可信多模态审核 <a class="header-anchor" href="#business-multimodal-moderation" aria-label="Permalink to “1. 可信多模态审核”">​</a></h3><blockquote><p><strong>资料</strong>：<a href="https://li.feishu.cn/wiki/LEbsw0CcViB3PIkWy5bcaRyGnJe" target="_blank" rel="noreferrer">Towards Trustworthy Multimodal Moderation via Policy-Aligned Reasoning and Hierarchical Labeling</a></p><p><strong>用途</strong>：关注审核策略、推理过程和层级标签体系，用于提升多模态内容审核的可解释性与策略一致性。</p><p><strong>核验 / 局限</strong>：核验数据来源、标签一致性、不同模态与风险类别的召回/误杀，以及策略更新后的迁移能力；可解释推理文本本身不保证决策真实可靠。</p></blockquote><h3 id="business-agent-rl-testing-static-fix" tabindex="-1">2. 智能体强化用于测试与静态检测修复 <a class="header-anchor" href="#business-agent-rl-testing-static-fix" aria-label="Permalink to “2. 智能体强化用于测试与静态检测修复”">​</a></h3><blockquote><p><strong>资料</strong>：<a href="https://li.feishu.cn/docx/Vh1XdxoX4ob8CBx6iy5c6QhYndQ?preview_comment_id=7654924138213117125" target="_blank" rel="noreferrer">智能体强化在测试用例和静态检测修复的应用</a></p><p><strong>用途</strong>：在有“规则”判断的 Agent 场景中，通过 guide、指向性 mask、拒绝采样等方法优化测试生成与静态检测修复。</p><p><strong>核验 / 局限</strong>：分别做 guide、mask、拒绝采样的消融，核验规则判定器的误差、奖励投机、修复通过率和回归风险；规则可判定不代表真实语义已覆盖。</p></blockquote><h3 id="business-medical-agent-ant-a-fu" tabindex="-1">3. 蚂蚁阿福医疗 Agent <a class="header-anchor" href="#business-medical-agent-ant-a-fu" aria-label="Permalink to “3. 蚂蚁阿福医疗 Agent”">​</a></h3><blockquote><p><strong>资料</strong>：<a href="https://mp.weixin.qq.com/s/GQwCRSrXBjSlTE4TEY_wfQ" target="_blank" rel="noreferrer">蚂蚁阿福：从 0 到生产的医疗 Agent 工程化落地</a></p><p><strong>用途</strong>：提供医疗 Agent 从原型到生产的工程案例，用于分析知识、工具、评测、风控和运营闭环。</p><p><strong>核验 / 局限</strong>：医疗属于高风险场景，应核验临床证据、数据合规、医生审核、拒答与追责机制；企业案例中的指标和实现细节可能不完整。</p></blockquote><h2 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to “安全”">​</a></h2><h3 id="security-joern-cpg" tabindex="-1">1. Joern 与代码属性图 <a class="header-anchor" href="#security-joern-cpg" aria-label="Permalink to “1. Joern 与代码属性图”">​</a></h3><blockquote><p><strong>资料</strong>：<a href="https://cloud.tencent.com/developer/article/2345095" target="_blank" rel="noreferrer">Joern 与 CPG</a></p><p><strong>用途</strong>：理解如何把语法、控制流和数据流统一到代码属性图中，支撑漏洞查询与污点分析。</p><p><strong>核验 / 局限</strong>：用目标语言和真实漏洞样例核验前端解析、跨过程数据流、查询准确率与性能；二手文章应与 Joern 官方文档和当前版本对照。</p></blockquote><h3 id="security-tree-sitter" tabindex="-1">2. Tree-sitter <a class="header-anchor" href="#security-tree-sitter" aria-label="Permalink to “2. Tree-sitter”">​</a></h3><blockquote><p><strong>资料</strong>：<a href="https://zhuanlan.zhihu.com/p/716273346" target="_blank" rel="noreferrer">Tree-sitter</a></p><p><strong>用途</strong>：理解增量语法解析及多语言语法树，用于代码索引、编辑器能力和轻量静态分析。</p><p><strong>核验 / 局限</strong>：核验目标语言 grammar 的完整性、错误恢复和版本兼容；Tree-sitter 主要提供语法结构，不能单独替代语义、控制流和数据流分析。</p></blockquote><h3 id="security-tbd-3" tabindex="-1">3. 待补安全条目 <a class="header-anchor" href="#security-tbd-3" aria-label="Permalink to “3. 待补安全条目”">​</a></h3><blockquote><p><strong>资料</strong>：原始笔记当前为空，尚未提供可定位的安全主题或链接。</p><p><strong>用途</strong>：保留该编号，如实标记索引中的待补位置。</p><p><strong>核验 / 局限</strong>：后续需补充标题、来源链接、预期用途与核验标准；在补充前不应据此推导任何安全结论。</p></blockquote>',52))])}const P=i(b,[["render",m]]);export{_ as __pageData,P as default};
